def main():
    ap = argparse.ArgumentParser()
    ap.add_argument("--datasets", default=str(ROOT / "datasets"))
    ap.add_argument("--export", default=str(ROOT / "export" / "trajectories_v1_01.jsonl"))
    ap.add_argument("--out", default=str(ROOT / "team" / "checkpoints"))
    ap.add_argument("--seed", type=int, default=42)
    ap.add_argument("--holdout", type=float, default=0.2)
    args = ap.parse_args()

    datasets_dir = Path(args.datasets)
    out_dir = Path(args.out)
    lookup = load_validation_feature_lookup(datasets_dir)

    # --- Stage 1: complexity model ---
    cx_feats, cx_labels, cx_ids = load_labeled_complexity(datasets_dir)
    tr_idx, te_idx = split_indices(len(cx_feats), args.holdout, args.seed)

    cx_train_f = [cx_feats[i] for i in tr_idx]
    cx_train_y = [cx_labels[i] for i in tr_idx]
    cx_test_f = [cx_feats[i] for i in te_idx]
    cx_test_y = [cx_labels[i] for i in te_idx]

    complexity = ComplexityModel().fit(cx_train_f, cx_train_y)

    pred_scores = [complexity.predict(f)["complexity_score"] for f in cx_test_f]
    true_scores = [y["complexity_score"] for y in cx_test_y]
    pred_bands = [complexity.predict(f)["complexity_band"] for f in cx_test_f]
    true_bands = [y["complexity_band"] for y in cx_test_y]

    cx_metrics = {
        "n_train": len(tr_idx),
        "n_test": len(te_idx),
        "score_mae": round(mae(true_scores, pred_scores), 3),
        "band_accuracy": round(band_acc(true_bands, pred_bands), 3),
    }

    # --- Stage 2: router on export (exclude validation ids from train) ---
    val_ids = set(cx_ids)
    rt_feats, rt_models, rt_ids = load_router_training(Path(args.export), lookup)
    router_train = [(f, m) for f, m, rid in zip(rt_feats, rt_models, rt_ids) if rid not in val_ids]
    router_test = [(f, m) for f, m, rid in zip(rt_feats, rt_models, rt_ids) if rid in val_ids]

    router = RouterModel(complexity=complexity)
    router.fit([f for f, _ in router_train], [m for _, m in router_train])

    rt_preds = [router.route(f, logged_model=m)["routed_model"] for f, m in router_test]
    rt_true = [m for _, m in router_test]
    rt_acc = sum(p == t for p, t in zip(rt_preds, rt_true)) / max(1, len(rt_true))

    # top-1 same-tier accuracy (group opus/sonnet/fable/gpt)
    def tier(m: str) -> str:
        if m.startswith("claude-opus"):
            return "opus"
        if m.startswith("claude-sonnet"):
            return "sonnet"
        if m.startswith("claude-fable"):
            return "fable"
        return "gpt"

    tier_acc = sum(tier(p) == tier(t) for p, t in zip(rt_preds, rt_true)) / max(1, len(rt_true))

    router_metrics = {
        "n_train": len(router_train),
        "n_test_validation_ids": len(router_test),
        "exact_accuracy": round(rt_acc, 3),
        "tier_accuracy": round(tier_acc, 3),
        "classes": ROUTER_CLASSES,
    }

    # Refit on all labeled / non-holdout data for the saved checkpoint.
    complexity_final = ComplexityModel().fit(cx_feats, cx_labels)
    router_final = RouterModel(complexity=complexity_final)
    router_final.fit([f for f, _ in router_train], [m for _, m in router_train])

    payload = {
        "schema_version": "munich_ehl_router_model_v1",
        "seed": args.seed,
        "feature_names": FEATURE_NAMES,
        "complexity_metrics": cx_metrics,
        "router_metrics": router_metrics,
        "router": router_final.to_dict(),
    }
    ckpt = out_dir / "model.json"
    save_checkpoint(ckpt, payload)

    print("=== Complexity model (holdout) ===")
    for k, v in cx_metrics.items():
        print(f"  {k}: {v}")
    print("=== Router (on validation request_ids) ===")
    for k, v in router_metrics.items():
        print(f"  {k}: {v}")
    print(f"wrote {ckpt}")


if __name__ == "__main__":
    main()
#!/usr/bin/env python3
"""Route trajectories with trained checkpoint + cache-aware cost report.

Usage (from repo root):
  python team/model/predict.py export/
  python team/model/predict.py export/trajectories_v1_01.jsonl --checkpoint team/checkpoints/model.json
"""
from __future__ import annotations

import argparse
import json
import sys
from pathlib import Path

ROOT = Path(__file__).resolve().parents[2]
sys.path.insert(0, str(ROOT / "team"))
sys.path.insert(0, str(ROOT / "scripts"))

from cost_model import load_pricing, logged_route, trajectory_cost  # noqa: E402
from load_trajectories import group_trajectories, iter_requests  # noqa: E402
from model.features import features_for_request, load_validation_feature_lookup  # noqa: E402
from model.router import RouterModel  # noqa: E402


def load_router(checkpoint: Path) -> RouterModel:
    payload = json.loads(checkpoint.read_text())
    return RouterModel.from_dict(payload["router"])


def route_trajectory(
    key: str, calls: list[dict], router: RouterModel, lookup: dict
) -> list[str]:
    """Pick model from first call's static features; apply to whole trajectory."""
    first = calls[0]
    feat = features_for_request(first, request_id=key, lookup=lookup)
    chosen = router.route(feat, logged_model=first["model"])["routed_model"]
    return [chosen for _ in calls]


def main():
    ap = argparse.ArgumentParser()
    ap.add_argument("export", help="export/ directory or trajectories_v1_01.jsonl")
    ap.add_argument("--checkpoint", default=str(ROOT / "team" / "checkpoints" / "model.json"))
    ap.add_argument("--datasets", default=str(ROOT / "datasets"))
    ap.add_argument("--out", default=str(ROOT / "results" / "team_routes.jsonl"))
    args = ap.parse_args()

    export_path = Path(args.export)
    router = load_router(Path(args.checkpoint))
    lookup = load_validation_feature_lookup(args.datasets)
    pricing = load_pricing()

    if export_path.is_dir():
        groups = group_trajectories(r for _, chunk, r in iter_requests(export_path))
    else:
        groups = {}
        with open(export_path) as f:
            for i, line in enumerate(f, start=1):
                if not line.strip():
                    continue
                req = json.loads(line)
                rid = f"{export_path.name}:{i}"
                groups[rid] = [req]

    Path(args.out).parent.mkdir(parents=True, exist_ok=True)
    tot_logged = tot_routed = 0.0
    with open(args.out, "w") as out:
        for key, calls in groups.items():
            logged = logged_route(calls)
            routed = route_trajectory(key, calls, router, lookup)
            c_logged, _ = trajectory_cost(calls, logged, pricing)
            c_routed, _ = trajectory_cost(calls, routed, pricing)
            tot_logged += c_logged
            tot_routed += c_routed
            out.write(
                json.dumps(
                    {
                        "trajectory": key,
                        "n_calls": len(calls),
                        "logged_model": logged[0],
                        "route": routed,
                        "cost_logged_usd": round(c_logged, 6),
                        "cost_routed_usd": round(c_routed, 6),
                        "switches": sum(
                            1 for i in range(1, len(routed)) if routed[i] != routed[i - 1]
                        ),
                    }
                )
                + "\n"
            )

    delta = (tot_routed / tot_logged - 1) if tot_logged else 0.0
    print(f"logged cost:  ${tot_logged:,.4f}")
    print(f"routed cost:  ${tot_routed:,.4f}  ({delta:+.1%})")
    print(f"wrote {args.out}")


if __name__ == "__main__":
    main()
#!/usr/bin/env python3
"""Inject results/dashboard_data.json into dashboard/template.html -> results/dashboard.html

Full refresh after new results land:
    python scripts/build_dashboard_data.py
    python dashboard/build.py
"""
import json, sys
from pathlib import Path

ROOT = Path(__file__).resolve().parent.parent
TPL = ROOT / "dashboard" / "template.html"
DATA = ROOT / "results" / "dashboard_data.json"
OUT = ROOT / "results" / "dashboard.html"
TOKEN = "/*__DASHBOARD_DATA__*/"

def main():
    if not DATA.exists():
        sys.exit(f"missing {DATA} — run scripts/build_dashboard_data.py first")
    html = TPL.read_text(encoding="utf-8")
    if TOKEN not in html:
        sys.exit(f"placeholder {TOKEN} not found in {TPL}")
    payload = json.dumps(json.loads(DATA.read_text(encoding="utf-8")), separators=(",", ":"))
    # </script> inside the JSON would close the host <script> tag early
    payload = payload.replace("</", "<\\/")
    OUT.parent.mkdir(exist_ok=True)
    OUT.write_text(html.replace(TOKEN, payload), encoding="utf-8")
    print(f"wrote {OUT}  ({OUT.stat().st_size:,} bytes)")

if __name__ == "__main__":
    main()
